from __future__ import annotations

from dataclasses import dataclass
from pathlib import Path
from typing import Any

import yaml

CANONICAL_TASKS = (
    "steels",
    "expt_gap",
    "glass",
    "expt_is_metal",
    "jdft2d",
    "dielectric",
    "log_kvrh",
    "log_gvrh",
    "perovskites",
    "phonons",
    "mp_gap",
    "mp_is_metal",
    "mp_e_form",
)

# These are aliases only.  No new indices are generated by Stage2.
SPLIT_ROLE_TO_MANIFEST_ROLE = {
    "train": "holdout_train",
    "val": "holdout_val",
    "test": "outer_test",
}


@dataclass(frozen=True)
class ExpertSpec:
    expert_id: str
    source_task: str
    provider: str
    hidden_dim: int
    export_root: Path
    input_modality: str
    representation_kind: str


@dataclass(frozen=True)
class ExpertPool:
    path: Path
    experts: tuple[ExpertSpec, ...]
    anchor_map: dict[str, str]

    @property
    def expert_ids(self) -> tuple[str, ...]:
        return tuple(value.expert_id for value in self.experts)

    @property
    def hidden_dims(self) -> dict[str, int]:
        return {value.expert_id: value.hidden_dim for value in self.experts}

    def anchor_for(self, task: str) -> str:
        return self.anchor_map[task]


def _mapping(value: Any, label: str) -> dict[str, Any]:
    if not isinstance(value, dict):
        raise ValueError(f"{label} must be a mapping")
    return value


def load_expert_pool(path: Path) -> ExpertPool:
    path = path.expanduser().resolve()
    payload = _mapping(yaml.safe_load(path.read_text(encoding="utf-8")), "expert pool")
    if int(payload.get("schema_version", -1)) != 12:
        raise ValueError("Frozen expert pool requires schema_version: 12")
    if payload.get("configuration_status") != "frozen_before_stage2":
        raise ValueError(
            "Frozen expert pool must be copied from the template, audited, and marked "
            "configuration_status: frozen_before_stage2"
        )
    if payload.get("protocol") != "one_strongest_frozen_expert_per_task_v1":
        raise ValueError("Unexpected frozen expert-pool protocol")
    if payload.get("split_protocol") != "reuse_stage1_train_val_test_exactly_v1":
        raise ValueError("Expert pool does not pin the simplified Stage1 split reuse")
    if payload.get("relation_screening") not in {"none", False}:
        raise ValueError("Expert inputs must not apply cross-task property/relation screening")

    raw_experts = payload.get("experts")
    if not isinstance(raw_experts, list) or len(raw_experts) != len(CANONICAL_TASKS):
        raise ValueError("The expert pool requires exactly 13 logical experts")
    experts: list[ExpertSpec] = []
    base = path.parent
    for raw in raw_experts:
        value = _mapping(raw, "expert")
        export_root = Path(str(value["export_root"])).expanduser()
        if not export_root.is_absolute():
            export_root = (base / export_root).resolve()
        spec = ExpertSpec(
            expert_id=str(value["expert_id"]),
            source_task=str(value["source_task"]),
            provider=str(value["provider"]),
            hidden_dim=int(value["hidden_dim"]),
            export_root=export_root,
            input_modality=str(value.get("input_modality", "unknown")),
            representation_kind=str(value.get("representation_kind", "")),
        )
        if spec.source_task not in CANONICAL_TASKS:
            raise ValueError(f"Unknown source task for {spec.expert_id}: {spec.source_task}")
        if spec.hidden_dim < 1:
            raise ValueError(f"Invalid hidden dimension for {spec.expert_id}")
        if spec.representation_kind != "task_trained_hidden":
            raise ValueError(
                f"{spec.expert_id} must export a task-trained hidden representation; "
                "fixed descriptors are not accepted as Stage2 expert hidden states"
            )
        experts.append(spec)
    expert_ids = [value.expert_id for value in experts]
    if len(set(expert_ids)) != len(expert_ids):
        raise ValueError("Logical expert IDs must be unique")
    if set(value.source_task for value in experts) != set(CANONICAL_TASKS):
        raise ValueError("The expert pool requires one logical source expert for every canonical task")

    anchor_map = {
        str(key): str(value)
        for key, value in _mapping(payload.get("anchor_map"), "anchor_map").items()
    }
    if set(anchor_map) != set(CANONICAL_TASKS):
        raise ValueError("anchor_map must cover exactly the 13 canonical tasks")
    by_id = {value.expert_id: value for value in experts}
    for task, expert_id in anchor_map.items():
        if expert_id not in by_id:
            raise ValueError(f"Anchor {expert_id} for {task} is not in the expert pool")
        if by_id[expert_id].source_task != task:
            raise ValueError(
                f"Anchor {expert_id} is trained for {by_id[expert_id].source_task}, not {task}"
            )
    return ExpertPool(path=path, experts=tuple(experts), anchor_map=anchor_map)


def protocol_receipt(pool: ExpertPool) -> dict[str, Any]:
    checkpoint_consistent = all(
        value.provider == "mattervial_modnet_0.4.5_checkpoint_consistent_v12_2"
        for value in pool.experts
    )
    anchorboost_pool = (
        any(
            value.provider == "mattervial_modnet_0.4.5_checkpoint_consistent_v12_2"
            for value in pool.experts
        )
        and any(
            value.provider == "anchorboost_v2_fixed_checkpoint_replay_v15_2"
            for value in pool.experts
        )
    )
    jmp_three_pool = (
        sum(
            value.provider == "jmp_l_official_checkpoint_consistent_v17"
            for value in pool.experts
        )
        == 3
        and sum(
            value.provider == "mattervial_modnet_0.4.5_checkpoint_consistent_v12_2"
            for value in pool.experts
        )
        == 8
        and sum(
            value.provider == "anchorboost_v2_fixed_checkpoint_replay_v15_2"
            for value in pool.experts
        )
        == 2
    )
    jmp_five_pool = (
        sum(
            value.provider == "jmp_l_official_checkpoint_consistent_v17"
            for value in pool.experts
        )
        == 3
        and sum(
            value.provider == "jmp_l_frozen_outer_checkpoint_replay_v17_12"
            for value in pool.experts
        )
        == 2
        and {
            value.source_task
            for value in pool.experts
            if value.provider
            in {
                "jmp_l_official_checkpoint_consistent_v17",
                "jmp_l_frozen_outer_checkpoint_replay_v17_12",
            }
        }
        == {"jdft2d", "perovskites", "phonons", "mp_gap", "mp_e_form"}
        and sum(
            value.provider == "mattervial_modnet_0.4.5_checkpoint_consistent_v12_2"
            for value in pool.experts
        )
        == 6
        and sum(
            value.provider == "anchorboost_v2_fixed_checkpoint_replay_v15_2"
            for value in pool.experts
        )
        == 1
        and sum(
            value.provider == "tpot_mat_official_selected_pipeline_v18"
            for value in pool.experts
        )
        == 1
        and pool.anchor_map.get("steels") == "tpot_mat_steels_anchor"
    )
    tpot_steels_pool = (
        sum(
            value.provider == "tpot_mat_official_selected_pipeline_v18"
            for value in pool.experts
        )
        == 1
        and pool.anchor_map.get("steels") == "tpot_mat_steels_anchor"
        and sum(
            value.provider == "jmp_l_official_checkpoint_consistent_v17"
            for value in pool.experts
        )
        == 3
        and sum(
            value.provider == "mattervial_modnet_0.4.5_checkpoint_consistent_v12_2"
            for value in pool.experts
        )
        == 8
        and sum(
            value.provider == "anchorboost_v2_fixed_checkpoint_replay_v15_2"
            for value in pool.experts
        )
        == 1
    )
    return {
        "schema_version": (
            "18.0"
            if tpot_steels_pool
            else "17.12"
            if jmp_five_pool
            else "17.0"
            if jmp_three_pool
            else ("12.2" if checkpoint_consistent else ("15.3" if anchorboost_pool else 12))
        ),
        "protocol": "one_strongest_frozen_expert_per_task_v1",
        "task_order": list(CANONICAL_TASKS),
        "expert_order": list(pool.expert_ids),
        "anchor_map": dict(pool.anchor_map),
        "split_mapping": dict(SPLIT_ROLE_TO_MANIFEST_ROLE),
        "stage1_frozen": True,
        "inner_oof": (
            "provider_specific;TPOT_and_JMP_outer_fold_checkpoint_replay"
            if tpot_steels_pool
            else "JMP5_and_TPOT_outer_fold_checkpoint_replay;remaining_provider_frozen_exports"
            if jmp_five_pool
            else "mattervial_own_task_only;JMP_outer_fold_checkpoint_replay"
            if jmp_three_pool
            else ("mattervial_own_task_only" if anchorboost_pool else checkpoint_consistent)
        ),
        "nested_cv": False,
        "outer_refit": (
            checkpoint_consistent or anchorboost_pool or tpot_steels_pool or jmp_five_pool
        ),
        "jmp_l_promoted_tasks": (
            ["jdft2d", "perovskites", "phonons", "mp_gap", "mp_e_form"]
            if jmp_five_pool
            else ["jdft2d", "perovskites", "phonons"]
            if (jmp_three_pool or tpot_steels_pool)
            else []
        ),
        "tpot_mat_promoted_tasks": (
            ["steels"] if (tpot_steels_pool or jmp_five_pool) else []
        ),
        "checkpoint_consistency": (
            "own_task_inner_oof_train_val_and_outer_refit_test;"
            "cross_task_outer_refit_all_roles"
            if checkpoint_consistent
            else (
                "provider_specific: TPOT-Mat and JMP frozen Stage1 outer-k checkpoints "
                "replay all Stage2 outer-k roles with no retraining; remaining providers "
                "retain their frozen exports"
                if tpot_steels_pool
                else
                "provider_specific: five JMP and one TPOT-steels frozen Stage1 outer-k "
                "checkpoints replay all Stage2 outer-k roles one-to-one; remaining "
                "providers retain their existing frozen exports"
                if jmp_five_pool
                else
                "provider_specific: JMP frozen Stage1 outer-k checkpoint replays all "
                "Stage2 outer-k roles with no retraining; MatterVial and AnchorBoost "
                "retain frozen V15.3 exports"
                if jmp_three_pool
                else
                "provider_specific: mattervial own-task inner-oof/outer-refit and "
                "cross-task outer-refit; anchorboost own-task holdout/outer-refit and "
                "composition-cross-task outer-refit"
                if anchorboost_pool
                else "holdout_train_val_and_outer_refit_test"
            )
        ),
        "relation_screening": "none",
        "availability_mask_policy": "technical_inability_only",
        "label_source": "immutable_task_manifest_only",
    }
